import subprocess

for np in [2, 3, 4, 5, 6]:
    bots = [f'python3 test_bot.py bot{i}' for i in range(np)]
    for seed in [1, 2, 3, 4, 5]:
        cmd = ['./executable', '-s', str(seed), '-r'] + bots
        proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        wh = proc.stdout.splitlines()[2*np]
        print(f'NP: {np}, Seed: {seed} -> Wh: {wh}')
""}

