{"command":"python3 -c "
from combat_test import run_test

# P1 moves down 2 steps to (5,4)
# P2 moves up 3 steps to (5,4)
bot1 = '''import sys
sys.stdin.readline(); sys.stdin.readline(); sys.stdin.readline(); sys.stdin.readline()
print(\"B1\"); sys.stdout.flush()
for turn in range(1, 50):
    sys.stdin.readline()
    if turn == 10: print(\"5 2 3\") # move SOUTH to (5,3)
    elif turn == 11: print(\"5 3 3\") # move SOUTH to (5,4)
    else: print(\"\")
    sys.stdout.flush()
'''

bot2 = '''import sys
sys.stdin.readline(); sys.stdin.readline(); sys.stdin.readline(); sys.stdin.readline()
print(\"B2\"); sys.stdout.flush()
for turn in range(1, 50):
    sys.stdin.readline()
    if turn == 11: print(\"5 7 1\") # move NORTH to (5,6)
    elif turn == 12: print(\"5 6 1\") # move NORTH to (5,5)
    elif turn == 13: print(\"5 5 1\") # move NORTH to (5,4)
    else: print(\"\")
    sys.stdout.flush()
'''

d = run_test(bot1, bot2)
for f_idx in range(10, 15):
    print(f'Frame {f_idx}:')
    print('  (5,3):', d['frames'][f_idx][3][5])
    print('  (5,4):', d['frames'][f_idx][4][5])
    print('  (5,5):', d['frames'][f_idx][5][5])
""}

