    std::vector<std::vector<double>> tile_str(th, std::vector<double>(tw, 0.0));

    int num_centers = std::uniform_int_distribution<int>(2, std::max(2, (tw * th) / 10))(prng);
    struct Center { double x, y, val; };
    std::vector<Center> centers(num_centers);
    for (int i = 0; i < num_centers; ++i) {
        centers[i].x = std::uniform_real_distribution<double>(0, tw)(prng);
        centers[i].y = std::uniform_real_distribution<double>(0, th)(prng);
        centers[i].val = std::uniform_real_distribution<double>(5.0, 15.0)(prng);
    }

    for (int r = 0; r < th; ++r) {
        for (int c = 0; c < tw; ++c) {
            double sum_val = 0.0;
            double sum_weight = 0.0;
            for (const auto& center : centers) {
                double dx = std::abs(c - center.x);
                double dy = std::abs(r - center.y);
                if (dx > tw / 2.0) dx = tw - dx;
                if (dy > th / 2.0) dy = th - dy;
                double dist_sq = dx * dx + dy * dy;
                double w = 1.0 / (dist_sq + 1.0);
                sum_val += center.val * w;
                sum_weight += w;
            }
            tile_prod[r][c] = sum_val / sum_weight;
        }
    }

    // Smooth production
    for (int pass = 0; pass < 2; ++pass) {
        auto copy = tile_prod;
        for (int r = 0; r < th; ++r) {
            for (int c = 0; c < tw; ++c) {
                double sum = 0.0;
                for (int dr = -1; dr <= 1; ++dr) {
                    for (int dc = -1; dc <= 1; ++dc) {
                        int nr = (r + dr + th) % th;
                        int nc = (c + dc + tw) % tw;
                        sum += copy[nr][nc];
                    }
                }
                tile_prod[r][c] = sum / 9.0;
            }
        }
    }

    // Scale production
    double max_p = 0.0;
    for (int r = 0; r < th; ++r) {
        for (int c = 0; c < tw; ++c) {
            if (tile_prod[r][c] > max_p) max_p = tile_prod[r][c];
        }
    }
    double scale = (max_p > 0.0) ? (15.0 / max_p) : 1.0;

    for (int r = 0; r < th; ++r) {
        for (int c = 0; c < tw; ++c) {
            int p = std::round(tile_prod[r][c] * scale);
            if (p < 1) p = 1;
            if (p > 15) p = 15;
            tile_prod[r][c] = p;

            // Generate strength inversely correlated with production
            int base_str = (15 - p) * 12 + std::uniform_int_distribution<int>(-15, 15)(prng);
            if (base_str < 1) base_str = 1;
            if (base_str > 255) base_str = 255;
            tile_str[r][c] = base_str;
        }
    }

    // Replicate tile across map
    for (int gr = 0; gr < rows; ++gr) {
        for (int gc = 0; gc < cols; ++gc) {
            for (int r = 0; r < th; ++r) {
                for (int c = 0; c < tw; ++c) {
                    int map_r = gr * th + r;
                    int map_c = gc * tw + c;
                    map.contents[map_r][map_c].owner = 0;
                    map.contents[map_r][map_c].production = (unsigned char)tile_prod[r][c];
                    map.contents[map_r][map_c].strength = (unsigned char)tile_str[r][c];
                }
            }
        }
    }

    // Assign starting locations for players
    // Pick lowest production cell in each tile for each player
    int p_idx = 0;
    for (int gr = 0; gr < rows; ++gr) {
        for (int gc = 0; gc < cols; ++gc) {
            if (p_idx >= num_players) break;
            int best_r = 0, best_c = 0;
            int min_p = 999, min_s = 999;
            for (int r = 0; r < th; ++r) {
                for (int c = 0; c < tw; ++c) {
                    int map_r = gr * th + r;
                    int map_c = gc * tw + c;
                    int p = map.contents[map_r][map_c].production;
                    int s = map.contents[map_r][map_c].strength;
                    if (p < min_p || (p == min_p && s < min_s)) {
                        min_p = p;
                        min_s = s;
                        best_r = map_r;
                        best_c = map_c;
                    }
                }
            }
            map.contents[best_r][best_c].owner = p_idx + 1;
            p_idx++;
        }
    }

    return map;
}
