#include "Game.hpp"

Game::Game(const GameOptions& opts) : options(opts) {
    if (!options.seed_given) {
        options.seed = std::chrono::system_clock::now().time_since_epoch().count();
    }

    if (!options.replay_directory.empty() && options.replay_directory.back() != '/') {
        options.replay_directory += '/';
    }

    if (options.n_players > 0 && options.bot_commands.size() == 1) {
        num_players = options.n_players;
    } else {
        num_players = options.bot_commands.size();
    }

    map = Map::generateMap(options.width, options.height, num_players, options.seed);
    max_turns = std::floor(10.0 * std::sqrt((double)map.width * (double)map.height));

    stats.resize(num_players);
    for (int i = 0; i < num_players; ++i) {
        stats[i].id = i + 1;
        stats[i].alive = true;
        stats[i].timed_out_init = false;
        stats[i].last_alive_frame = 0;
        stats[i].territory = 0;
        stats[i].production = 0;
        stats[i].total_strength = 0;
        stats[i].rank = 0;

        if (i < (int)options.bot_commands.size()) {
            stats[i].command = options.bot_commands[i];
        } else {
            stats[i].command = options.bot_commands[0];
        }

        if (options.override_mode && i < (int)options.override_names.size()) {
            stats[i].name = options.override_names[i];
        } else {
            stats[i].name = "";
        }
    }
}

std::string Game::encodeMapState() {
    std::ostringstream ss;

    // RLE owner encoding
    std::vector<std::pair<int, int>> rle; // count, owner
    int current_owner = -1;
    int current_count = 0;

    for (int r = 0; r < map.height; ++r) {
        for (int c = 0; c < map.width; ++c) {
            int owner = map.contents[r][c].owner;
            if (owner == current_owner) {
                current_count++;
            } else {
                if (current_count > 0) {
                    rle.push_back({current_count, current_owner});
                }
                current_owner = owner;
                current_count = 1;
            }
        }
    }
    if (current_count > 0) {
        rle.push_back({current_count, current_owner});
    }

    for (size_t i = 0; i < rle.size(); ++i) {
        if (i > 0) ss << " ";
        ss << rle[i].first << " " << rle[i].second;
    }

    // Strengths
    for (int r = 0; r < map.height; ++r) {
        for (int c = 0; c < map.width; ++c) {
            ss << " " << (int)map.contents[r][c].strength;
        }
    }

    return ss.str();
}

