                    for (int dir = 0; dir < 5; ++dir) {
                        int nr = (r + dr[dir] + map.height) % map.height;
                        int nc = (c + dc[dir] + map.width) % map.width;

                        for (int q = 1; q <= num_players; ++q) {
                            if (q != p) {
                                damage[p] += moved[nr][nc][q];
                            }
                        }
                    }
                    if (map.contents[r][c].owner == 0) {
                        damage[p] += map.contents[r][c].strength;
                    }
                }

                int env_damage = 0;
                for (int p = 1; p <= num_players; ++p) {
                    env_damage += moved[r][c][p];
                }

                // Strengths after damage
                std::vector<int> rem_str(num_players + 1, 0);
                for (int p = 1; p <= num_players; ++p) {
                    rem_str[p] = std::max(0, moved[r][c][p] - damage[p]);
                }

                int rem_env = 0;
                if (map.contents[r][c].owner == 0) {
                    rem_env = std::max(0, (int)map.contents[r][c].strength - env_damage);
                }

                // Determine winner at (r, c)
                int orig_owner = map.contents[r][c].owner;
                if (orig_owner == 0) {
                    int max_p = 0, max_v = rem_env;
                    bool tie = false;
                    for (int p = 1; p <= num_players; ++p) {
                        if (rem_str[p] > max_v) {
                            max_v = rem_str[p];
                            max_p = p;
                            tie = false;
                        } else if (rem_str[p] == max_v && rem_str[p] > 0) {
                            tie = true;
                        }
                    }

                    if (max_p != 0 && !tie) {
                        next_map.contents[r][c].owner = max_p;
                        next_map.contents[r][c].strength = max_v;
                    } else if (rem_env > 0) {
                        next_map.contents[r][c].owner = 0;
                        next_map.contents[r][c].strength = rem_env;
                    } else {
                        next_map.contents[r][c].owner = 0;
                        next_map.contents[r][c].strength = 0;
                    }
                } else {
                    int max_p = 0, max_v = 0;
                    bool tie = false;
                    for (int p = 1; p <= num_players; ++p) {
                        if (rem_str[p] > max_v) {
                            max_v = rem_str[p];
                            max_p = p;
                            tie = false;
                        } else if (rem_str[p] == max_v && rem_str[p] > 0) {
                            tie = true;
                        }
                    }

                    if (max_p != 0 && !tie) {
                        next_map.contents[r][c].owner = max_p;
                        next_map.contents[r][c].strength = max_v;
                    } else {
                        next_map.contents[r][c].owner = orig_owner;
                        next_map.contents[r][c].strength = 0;
                    }
                }
            }
        }

        map = next_map;

        // Check player survival
        std::vector<int> counts(num_players + 1, 0);
        for (int r = 0; r < map.height; ++r) {
            for (int c = 0; c < map.width; ++c) {
                if (map.contents[r][c].owner > 0) {
                    counts[map.contents[r][c].owner]++;
                }
            }
        }

        for (int p = 1; p <= num_players; ++p) {
            if (stats[p - 1].alive) {
                if (counts[p] > 0) {
                    stats[p - 1].last_alive_frame = turn;
                } else {
                    stats[p - 1].alive = false;
                }
            }
        }

        // Record frame
        std::vector<std::vector<std::vector<int>>> cur_frame(map.height, std::vector<std::vector<int>>(map.width, std::vector<int>(2)));
        for (int r = 0; r < map.height; ++r) {
            for (int c = 0; c < map.width; ++c) {
                cur_frame[r][c][0] = map.contents[r][c].owner;
                cur_frame[r][c][1] = map.contents[r][c].strength;
            }
        }
        replay_frames.push_back(cur_frame);
    }

    // Kill all bots
    for (int i = 0; i < num_bots; ++i) {
        Networking::killBot(bots[i]);
    }

    // Calculate final stats & rankings
    for (int p = 1; p <= num_players; ++p) {
        stats[p - 1].territory = 0;
        stats[p - 1].production = 0;
        stats[p - 1].total_strength = 0;

        for (int r = 0; r < map.height; ++r) {
            for (int c = 0; c < map.width; ++c) {
                if (map.contents[r][c].owner == p) {
                    stats[p - 1].territory++;
                    stats[p - 1].production += map.contents[r][c].production;
                    stats[p - 1].total_strength += map.contents[r][c].strength;
                }
            }
        }
    }

    // Sort players for ranking
    std::vector<int> rank_order(num_players);
    for (int i = 0; i < num_players; ++i) rank_order[i] = i;

    std::stable_sort(rank_order.begin(), rank_order.end(), [&](int a, int b) {
        if (stats[a].last_alive_frame != stats[b].last_alive_frame) {
            return stats[a].last_alive_frame > stats[b].last_alive_frame;
        }
        if (stats[a].territory != stats[b].territory) {
            return stats[a].territory > stats[b].territory;
        }
        if (stats[a].production != stats[b].production) {
            return stats[a].production > stats[b].production;
        }
        if (stats[a].total_strength != stats[b].total_strength) {
            return stats[a].total_strength > stats[b].total_strength;
        }
        return a > b; // Higher player ID gets higher rank on tie
    });

    for (int r = 0; r < num_players; ++r) {
        stats[rank_order[r]].rank = r + 1;
    }

    // Generate filename
    long long timestamp = std::chrono::duration_cast<std::chrono::seconds>(
        std::chrono::system_clock::now().time_since_epoch()).count();
    std::string filename = options.replay_directory + std::to_string(timestamp) + "-" + std::to_string(options.seed) + ".hlt";

    if (!options.no_replay) {
        writeReplayFile(filename);
    }

    // Print summary
    if (options.quiet) {
        for (int i = 0; i < num_bots; ++i) {
            std::cout << options.bot_commands[i] << std::endl;
        }
        std::cout << map.width << " " << map.height << std::endl;
        if (!options.no_replay) {
            std::cout << filename << " " << options.seed << std::endl;
        }
        for (int i = 0; i < num_players; ++i) {
            std::cout << stats[i].id << " " << stats[i].rank << " " << stats[i].last_alive_frame << std::endl;
        }
    } else {
        if (!options.no_replay) {
            std::cout << "Map seed was " << options.seed << std::endl;
            std::cout << "Opening a file at " << filename << std::endl;
        }
        for (int i = 0; i < num_players; ++i) {
            if (stats[i].timed_out_init) {
                std::cout << "Player #" << stats[i].id << ", Bot #" << stats[i].id << "; timed out during Init, came in rank #" << stats[i].rank << " and was last alive on frame #-1!" << std::endl;
            } else {
                std::cout << "Player #" << stats[i].id << ", " << stats[i].name << ", came in rank #" << stats[i].rank << " and was last alive on frame #" << stats[i].last_alive_frame << "!" << std::endl;
            }
        }
    }
}

void Game::writeReplayFile(const std::string& filename) {
    std::ofstream ofs(filename);
    if (!ofs.is_open()) return;

    ofs << "{";
    ofs << "\"frames\":[";
    for (size_t f = 0; f < replay_frames.size(); ++f) {
        if (f > 0) ofs << ",";
        ofs << "[";
        for (int r = 0; r < map.height; ++r) {
            if (r > 0) ofs << ",";
            ofs << "[";
            for (int c = 0; c < map.width; ++c) {
                if (c > 0) ofs << ",";
                ofs << "[" << replay_frames[f][r][c][0] << "," << replay_frames[f][r][c][1] << "]";
            }
            ofs << "]";
        }
        ofs << "]";
    }
    ofs << "],";

    ofs << "\"height\":" << map.height << ",";

    ofs << "\"moves\":[";
    for (size_t m = 0; m < replay_moves.size(); ++m) {
        if (m > 0) ofs << ",";
        ofs << "[";
        for (int r = 0; r < map.height; ++r) {
            if (r > 0) ofs << ",";
            ofs << "[";
            for (int c = 0; c < map.width; ++c) {
                if (c > 0) ofs << ",";
                ofs << replay_moves[m][r][c];
            }
            ofs << "]";
        }
        ofs << "]";
    }
    ofs << "],";

    ofs << "\"num_frames\":" << replay_frames.size() << ",";
    ofs << "\"num_players\":" << num_players << ",";

    ofs << "\"player_names\":[";
    for (int i = 0; i < num_players; ++i) {
        if (i > 0) ofs << ",";
        ofs << "\"" << stats[i].name << "\"";
    }
    ofs << "],";

    ofs << "\"productions\":[";
    for (int r = 0; r < map.height; ++r) {
        if (r > 0) ofs << ",";
        ofs << "[";
        for (int c = 0; c < map.width; ++c) {
            if (c > 0) ofs << ",";
            ofs << (int)map.contents[r][c].production;
        }
        ofs << "]";
    }
    ofs << "],";

    ofs << "\"version\":11,";
    ofs << "\"width\":" << map.width;
    ofs << "}";

    ofs.close();
}
