#include "Networking.hpp"
#include <cstring>

BotProcess Networking::startBot(const std::string& command) {
    BotProcess bot;
    bot.pid = -1;
    bot.in_fd = -1;
    bot.out_fd = -1;
    bot.alive = false;
    bot.command = command;

    int pipe_in[2];  // host -> bot
    int pipe_out[2]; // bot -> host

    if (pipe(pipe_in) < 0 || pipe(pipe_out) < 0) {
        return bot;
    }

    pid_t pid = fork();
    if (pid < 0) {
        return bot;
    }

    if (pid == 0) {
        // Child process
        close(pipe_in[1]);
        close(pipe_out[0]);

        dup2(pipe_in[0], STDIN_FILENO);
        dup2(pipe_out[1], STDOUT_FILENO);

        int dev_null = open("/dev/null", O_WRONLY);
        if (dev_null >= 0) {
            dup2(dev_null, STDERR_FILENO);
            close(dev_null);
        }

        close(pipe_in[0]);
        close(pipe_out[1]);

        execl("/bin/sh", "sh", "-c", command.c_str(), (char*)NULL);
        _exit(127);
    } else {
        // Parent process
        close(pipe_in[0]);
        close(pipe_out[1]);

        bot.pid = pid;
        bot.in_fd = pipe_in[1];
        bot.out_fd = pipe_out[0];
        bot.alive = true;
    }

    return bot;
}

void Networking::sendString(const BotProcess& bot, const std::string& str) {
    if (!bot.alive || bot.in_fd < 0) return;
    std::string msg = str;
    if (msg.empty() || msg.back() != '\n') msg += '\n';
    ssize_t n = write(bot.in_fd, msg.c_str(), msg.length());
    (void)n;
}

ReadResult Networking::readLine(BotProcess& bot, int timeout_ms) {
    ReadResult res;
    res.success = false;
    res.line = "";

    if (!bot.alive || bot.out_fd < 0) return res;

    std::string result;
    while (true) {
        struct pollfd pfd;
        pfd.fd = bot.out_fd;
        pfd.events = POLLIN;

        int ret = poll(&pfd, 1, timeout_ms);
        if (ret <= 0) {
            // Timeout or error
            bot.alive = false;
            return res;
        }

        char ch;
        ssize_t n = read(bot.out_fd, &ch, 1);
        if (n <= 0) {
            bot.alive = false;
            return res;
        }

        if (ch == '\n') {
            if (!result.empty() && result.back() == '\r') {
                result.pop_back();
            }
            res.success = true;
            res.line = result;
            return res;
        }
        result += ch;
    }
}

void Networking::killBot(BotProcess& bot) {
    if (bot.pid > 0) {
        close(bot.in_fd);
        close(bot.out_fd);
        kill(bot.pid, SIGKILL);
        waitpid(bot.pid, NULL, WNOHANG);
        bot.alive = false;
    }
}
