#include "Game.hpp"

Game::Game(const GameOptions& opts) : options(opts) {
    if (!options.seed_given) {
        options.seed = std::chrono::system_clock::now().time_since_epoch().count();
    }

    if (!options.replay_directory.empty() && options.replay_directory.back() != '/') {
        options.replay_directory += '/';
    }

    if (options.n_players > 0 && options.bot_commands.size() == 1) {
        num_players = options.n_players;
    } else {
        num_players = options.bot_commands.size();
    }

    map = Map::generateMap(options.width, options.height, num_players, options.seed);
    max_turns = std::floor(10.0 * std::sqrt((double)map.width * (double)map.height));

    stats.resize(num_players);
    for (int i = 0; i < num_players; ++i) {
        stats[i].id = i + 1;
        stats[i].alive = true;
        stats[i].timed_out_init = false;
        stats[i].last_alive_frame = 0;
        stats[i].territory = 0;
        stats[i].production = 0;
        stats[i].total_strength = 0;
        stats[i].rank = 0;

        if (i < (int)options.bot_commands.size()) {
            stats[i].command = options.bot_commands[i];
        } else {
            stats[i].command = options.bot_commands[0];
        }

        if (options.override_mode && i < (int)options.override_names.size()) {
            stats[i].name = options.override_names[i];
        } else {
            stats[i].name = "";
        }
    }
}

std::string Game::encodeMapState() {
    std::ostringstream ss;

    // RLE owner encoding
    std::vector<std::pair<int, int>> rle; // count, owner
    int current_owner = -1;
    int current_count = 0;

    for (int r = 0; r < map.height; ++r) {
        for (int c = 0; c < map.width; ++c) {
            int owner = map.contents[r][c].owner;
            if (owner == current_owner) {
                current_count++;
            } else {
                if (current_count > 0) {
                    rle.push_back({current_count, current_owner});
                }
                current_owner = owner;
                current_count = 1;
            }
        }
    }
    if (current_count > 0) {
        rle.push_back({current_count, current_owner});
    }

    for (size_t i = 0; i < rle.size(); ++i) {
        if (i > 0) ss << " ";
        ss << rle[i].first << " " << rle[i].second;
    }

    // Strengths
    for (int r = 0; r < map.height; ++r) {
        for (int c = 0; c < map.width; ++c) {
            ss << " " << (int)map.contents[r][c].strength;
        }
    }

    return ss.str();
}

void Game::run() {
    // 1. Handshake
    int num_bots = options.bot_commands.size();
    bots.resize(num_bots);

    for (int i = 0; i < num_bots; ++i) {
        if (!options.quiet) {
            std::cout << options.bot_commands[i] << std::endl;
            std::cout << options.bot_commands[i] << std::endl;
        }
    }
    if (!options.quiet) {
        std::cout << map.width << " " << map.height << std::endl;
    }

    // Launch bots
    for (int i = 0; i < num_bots; ++i) {
        bots[i] = Networking::startBot(options.bot_commands[i]);
    }

    // Send init message
    std::ostringstream prod_ss;
    for (int r = 0; r < map.height; ++r) {
        for (int c = 0; c < map.width; ++c) {
            if (r > 0 || c > 0) prod_ss << " ";
            prod_ss << (int)map.contents[r][c].production;
        }
    }
    std::string prod_str = prod_ss.str();

    std::string initial_map_str = encodeMapState();

    for (int i = 0; i < num_bots; ++i) {
        if (!bots[i].alive) continue;
        std::ostringstream init_ss;
        init_ss << (i + 1) << "\n" << map.width << " " << map.height << "\n" << prod_str << "\n" << initial_map_str;
        Networking::sendString(bots[i], init_ss.str());
        if (!options.quiet) {
            std::cout << "Init Message sent to player " << (i + 1) << "." << std::endl;
        }
    }

    // Read bot names
    int init_timeout = options.no_timeout ? 0 : 30000;
    for (int i = 0; i < num_bots; ++i) {
        if (!bots[i].alive) {
            stats[i].alive = false;
            stats[i].timed_out_init = true;
            stats[i].last_alive_frame = -1;
            continue;
        }

        ReadResult res = Networking::readLine(bots[i], init_timeout);
        if (!res.success) {
            stats[i].alive = false;
            stats[i].timed_out_init = true;
            stats[i].last_alive_frame = -1;
            if (!options.quiet) {
                std::cout << "Bot #" << (i + 1) << " timeout or error (Unix) 0" << std::endl;
            }
        } else {
            if (!options.override_mode) {
                stats[i].name = res.line;
            }
            if (!options.quiet) {
                std::cout << "Init Message received from player " << (i + 1) << ", " << stats[i].name << "." << std::endl;
            }
        }
    }

    // Record Frame 0
    std::vector<std::vector<std::vector<int>>> frame0(map.height, std::vector<std::vector<int>>(map.width, std::vector<int>(2)));
    for (int r = 0; r < map.height; ++r) {
        for (int c = 0; c < map.width; ++c) {
            frame0[r][c][0] = map.contents[r][c].owner;
            frame0[r][c][1] = map.contents[r][c].strength;
        }
    }
    replay_frames.push_back(frame0);

    int turn_timeout = options.no_timeout ? 0 : 1000;

    // Turn loop
    int turn = 1;
    for (; turn <= max_turns; ++turn) {
        int active_players = 0;
        for (int i = 0; i < num_players; ++i) {
            if (stats[i].alive) active_players++;
        }

        if (num_players > 1 && active_players <= 1) break;
        if (num_players == 1 && active_players == 0) break;

        if (!options.quiet) {
            std::cout << "Turn " << turn << std::endl;
        }

        std::string map_state = encodeMapState();

        // Send map state to bots
        for (int i = 0; i < num_bots; ++i) {
            if (stats[i].alive) {
                Networking::sendString(bots[i], map_state);
            }
        }

        // Read responses
        std::vector<std::vector<int>> moves(map.height, std::vector<int>(map.width, 0));
        for (int i = 0; i < num_bots; ++i) {
            if (!stats[i].alive) continue;

            ReadResult res = Networking::readLine(bots[i], turn_timeout);

            if (!res.success) {
                if (!options.quiet) {
                    std::cout << "Bot #" << (i + 1) << " timeout or error (Unix) 0" << std::endl;
                }
                stats[i].alive = false;
                stats[i].last_alive_frame = turn - 1;
                for (int r = 0; r < map.height; ++r) {
                    for (int c = 0; c < map.width; ++c) {
                        if (map.contents[r][c].owner == i + 1) {
                            map.contents[r][c].owner = 0;
                        }
                    }
                }
                continue;
            }

            std::string line = res.line;

            // Validate character format
            bool invalid_char = false;
            for (char ch : line) {
                if (!std::isdigit(ch) && !std::isspace(ch) && ch != '+' && ch != '-') {
                    invalid_char = true;
                    break;
                }
            }

            if (invalid_char) {
                if (!options.quiet) {
                    std::cout << "Bot sent an invalid character - ejecting from game." << std::endl;
                }
                stats[i].alive = false;
                stats[i].last_alive_frame = turn - 1;
                // Disqualify player i: convert cells to owner 0
                for (int r = 0; r < map.height; ++r) {
                    for (int c = 0; c < map.width; ++c) {
                        if (map.contents[r][c].owner == i + 1) {
                            map.contents[r][c].owner = 0;
                        }
                    }
                }
                continue;
            }

            std::stringstream iss(line);
            int x, y, d;
            bool parse_err = false;
            while (iss >> x >> y >> d) {
                if (x < 0 || x >= map.width || y < 0 || y >= map.height || d < 0 || d > 4) {
                    parse_err = true;
                    break;
                }
                moves[y][x] = d;
            }

            if (parse_err) {
                if (!options.quiet) {
                    std::cout << "Bot #" << (i + 1) << " timeout or error (Unix) 0" << std::endl;
                }
                stats[i].alive = false;
                stats[i].last_alive_frame = turn - 1;
                for (int r = 0; r < map.height; ++r) {
                    for (int c = 0; c < map.width; ++c) {
                        if (map.contents[r][c].owner == i + 1) {
                            map.contents[r][c].owner = 0;
                        }
                    }
                }
            }
        }

        replay_moves.push_back(moves);

        // Execute turn updates
        // 1. STILL moves & production
        Map next_map = map;
        for (int r = 0; r < map.height; ++r) {
            for (int c = 0; c < map.width; ++c) {
                int owner = map.contents[r][c].owner;
                int move = moves[r][c];
                if (owner != 0 && move == 0) {
                    int p = map.contents[r][c].production;
                    int new_s = map.contents[r][c].strength + p;
                    if (new_s > 255) new_s = 255;
                    next_map.contents[r][c].strength = new_s;
                }
            }
        }

        // 2. Non-STILL moves aggregation
        // Pieces moving to target cells
        std::vector<std::vector<std::vector<int>>> moved(map.height, std::vector<std::vector<int>>(map.width, std::vector<int>(num_players + 1, 0)));

        for (int r = 0; r < map.height; ++r) {
            for (int c = 0; c < map.width; ++c) {
                int owner = map.contents[r][c].owner;
                int move = moves[r][c];

                if (owner != 0 && move != 0) {
                    int nr = r, nc = c;
                    if (move == 1) nr = (r - 1 + map.height) % map.height; // NORTH
                    else if (move == 2) nc = (c + 1) % map.width;         // EAST
                    else if (move == 3) nr = (r + 1) % map.height;         // SOUTH
                    else if (move == 4) nc = (c - 1 + map.width) % map.width; // WEST

                    moved[nr][nc][owner] += map.contents[r][c].strength;
                    next_map.contents[r][c].strength = 0;
                } else if (owner != 0 && move == 0) {
                    moved[r][c][owner] += next_map.contents[r][c].strength;
                }
            }
        }

        // Cap moved pieces per player at 255
        for (int r = 0; r < map.height; ++r) {
            for (int c = 0; c < map.width; ++c) {
                for (int p = 1; p <= num_players; ++p) {
                    if (moved[r][c][p] > 255) moved[r][c][p] = 255;
                }
            }
        }

        // 3. Combat resolution
        for (int r = 0; r < map.height; ++r) {
            for (int c = 0; c < map.width; ++c) {
                // Calculate damage to player p at (r, c)
                std::vector<int> damage(num_players + 1, 0);

                int dr[] = {0, -1, 0, 1, 0};
                int dc[] = {0, 0, 1, 0, -1};

                for (int p = 1; p <= num_players; ++p) {
                    for (int dir = 0; dir < 5; ++dir) {
                        int nr = (r + dr[dir] + map.height) % map.height;
                        int nc = (c + dc[dir] + map.width) % map.width;

                        for (int q = 1; q <= num_players; ++q) {
                            if (q != p) {
                                damage[p] += moved[nr][nc][q];
                            }
                        }
                    }
                    if (map.contents[r][c].owner == 0) {
                        damage[p] += map.contents[r][c].strength;
                    }
                }

                int env_damage = 0;
                for (int p = 1; p <= num_players; ++p) {
                    env_damage += moved[r][c][p];
                }

                // Strengths after damage
                std::vector<int> rem_str(num_players + 1, 0);
                for (int p = 1; p <= num_players; ++p) {
                    rem_str[p] = std::max(0, moved[r][c][p] - damage[p]);
                }

                int rem_env = 0;
                if (map.contents[r][c].owner == 0) {
                    rem_env = std::max(0, (int)map.contents[r][c].strength - env_damage);
                }

                // Determine winner at (r, c)
                int orig_owner = map.contents[r][c].owner;
                if (orig_owner == 0) {
                    int max_p = 0, max_v = rem_env;
                    bool tie = false;
                    for (int p = 1; p <= num_players; ++p) {
                        if (rem_str[p] > max_v) {
                            max_v = rem_str[p];
                            max_p = p;
                            tie = false;
                        } else if (rem_str[p] == max_v && rem_str[p] > 0) {
                            tie = true;
                        }
                    }

                    if (max_p != 0 && !tie) {
                        next_map.contents[r][c].owner = max_p;
                        next_map.contents[r][c].strength = max_v;
                    } else if (rem_env > 0) {
                        next_map.contents[r][c].owner = 0;
                        next_map.contents[r][c].strength = rem_env;
                    } else {
                        next_map.contents[r][c].owner = 0;
                        next_map.contents[r][c].strength = 0;
                    }
                } else {
                    int max_p = 0, max_v = 0;
                    bool tie = false;
                    for (int p = 1; p <= num_players; ++p) {
                        if (rem_str[p] > max_v) {
                            max_v = rem_str[p];
                            max_p = p;
                            tie = false;
                        } else if (rem_str[p] == max_v && rem_str[p] > 0) {
                            tie = true;
                        }
                    }

                    if (max_p != 0 && !tie) {
                        next_map.contents[r][c].owner = max_p;
                        next_map.contents[r][c].strength = max_v;
                    } else {
                        next_map.contents[r][c].owner = orig_owner;
                        next_map.contents[r][c].strength = 0;
                    }
                }
            }
        }

        map = next_map;

        // Check player survival
        std::vector<int> counts(num_players + 1, 0);
        for (int r = 0; r < map.height; ++r) {
            for (int c = 0; c < map.width; ++c) {
                if (map.contents[r][c].owner > 0) {
                    counts[map.contents[r][c].owner]++;
                }
            }
        }

        for (int p = 1; p <= num_players; ++p) {
            if (stats[p - 1].alive) {
                if (counts[p] > 0) {
                    stats[p - 1].last_alive_frame = turn;
                } else {
                    stats[p - 1].alive = false;
                }
            }
        }

        // Record frame
        std::vector<std::vector<std::vector<int>>> cur_frame(map.height, std::vector<std::vector<int>>(map.width, std::vector<int>(2)));
        for (int r = 0; r < map.height; ++r) {
            for (int c = 0; c < map.width; ++c) {
                cur_frame[r][c][0] = map.contents[r][c].owner;
                cur_frame[r][c][1] = map.contents[r][c].strength;
            }
        }
        replay_frames.push_back(cur_frame);
    }

    // Kill all bots
    for (int i = 0; i < num_bots; ++i) {
        Networking::killBot(bots[i]);
    }

    // Calculate final stats & rankings
    for (int p = 1; p <= num_players; ++p) {
        stats[p - 1].territory = 0;
        stats[p - 1].production = 0;
        stats[p - 1].total_strength = 0;

        for (int r = 0; r < map.height; ++r) {
            for (int c = 0; c < map.width; ++c) {
                if (map.contents[r][c].owner == p) {
                    stats[p - 1].territory++;
                    stats[p - 1].production += map.contents[r][c].production;
                    stats[p - 1].total_strength += map.contents[r][c].strength;
                }
            }
        }
    }

    // Sort players for ranking
    std::vector<int> rank_order(num_players);
    for (int i = 0; i < num_players; ++i) rank_order[i] = i;

    std::stable_sort(rank_order.begin(), rank_order.end(), [&](int a, int b) {
        if (stats[a].last_alive_frame != stats[b].last_alive_frame) {
            return stats[a].last_alive_frame > stats[b].last_alive_frame;
        }
        if (stats[a].territory != stats[b].territory) {
            return stats[a].territory > stats[b].territory;
        }
        if (stats[a].production != stats[b].production) {
            return stats[a].production > stats[b].production;
        }
        if (stats[a].total_strength != stats[b].total_strength) {
            return stats[a].total_strength > stats[b].total_strength;
        }
        return a > b; // Higher player ID gets higher rank on tie
    });

    for (int r = 0; r < num_players; ++r) {
        stats[rank_order[r]].rank = r + 1;
    }

    // Generate filename
    long long timestamp = std::chrono::duration_cast<std::chrono::seconds>(
        std::chrono::system_clock::now().time_since_epoch()).count();
    std::string filename = options.replay_directory + std::to_string(timestamp) + "-" + std::to_string(options.seed) + ".hlt";

    if (!options.no_replay) {
        writeReplayFile(filename);
    }

    // Print summary
    if (options.quiet) {
        for (int i = 0; i < num_bots; ++i) {
            std::cout << options.bot_commands[i] << std::endl;
        }
        std::cout << map.width << " " << map.height << std::endl;
        if (!options.no_replay) {
            std::cout << filename << " " << options.seed << std::endl;
        }
        for (int i = 0; i < num_players; ++i) {
            std::cout << stats[i].id << " " << stats[i].rank << " " << stats[i].last_alive_frame << std::endl;
        }
    } else {
        if (!options.no_replay) {
            std::cout << "Map seed was " << options.seed << std::endl;
            std::cout << "Opening a file at " << filename << std::endl;
        }
        for (int i = 0; i < num_players; ++i) {
            if (stats[i].timed_out_init) {
                std::cout << "Player #" << stats[i].id << ", Bot #" << stats[i].id << "; timed out during Init, came in rank #" << stats[i].rank << " and was last alive on frame #-1!" << std::endl;
            } else {
                std::cout << "Player #" << stats[i].id << ", " << stats[i].name << ", came in rank #" << stats[i].rank << " and was last alive on frame #" << stats[i].last_alive_frame << "!" << std::endl;
            }
        }
    }
}

void Game::writeReplayFile(const std::string& filename) {
    std::ofstream ofs(filename);
    if (!ofs.is_open()) return;

    ofs << "{";
    ofs << "\"frames\":[";
    for (size_t f = 0; f < replay_frames.size(); ++f) {
        if (f > 0) ofs << ",";
        ofs << "[";
        for (int r = 0; r < map.height; ++r) {
            if (r > 0) ofs << ",";
            ofs << "[";
            for (int c = 0; c < map.width; ++c) {
                if (c > 0) ofs << ",";
                ofs << "[" << replay_frames[f][r][c][0] << "," << replay_frames[f][r][c][1] << "]";
            }
            ofs << "]";
        }
        ofs << "]";
    }
    ofs << "],";

    ofs << "\"height\":" << map.height << ",";

    ofs << "\"moves\":[";
    for (size_t m = 0; m < replay_moves.size(); ++m) {
        if (m > 0) ofs << ",";
        ofs << "[";
        for (int r = 0; r < map.height; ++r) {
            if (r > 0) ofs << ",";
            ofs << "[";
            for (int c = 0; c < map.width; ++c) {
                if (c > 0) ofs << ",";
                ofs << replay_moves[m][r][c];
            }
            ofs << "]";
        }
        ofs << "]";
    }
    ofs << "],";

    ofs << "\"num_frames\":" << replay_frames.size() << ",";
    ofs << "\"num_players\":" << num_players << ",";

    ofs << "\"player_names\":[";
    for (int i = 0; i < num_players; ++i) {
        if (i > 0) ofs << ",";
        ofs << "\"" << stats[i].name << "\"";
    }
    ofs << "],";

    ofs << "\"productions\":[";
    for (int r = 0; r < map.height; ++r) {
        if (r > 0) ofs << ",";
        ofs << "[";
        for (int c = 0; c < map.width; ++c) {
            if (c > 0) ofs << ",";
            ofs << (int)map.contents[r][c].production;
        }
        ofs << "]";
    }
    ofs << "],";

    ofs << "\"version\":11,";
    ofs << "\"width\":" << map.width;
    ofs << "}";

    ofs.close();
}
