std::string Game::encodeMapState() {
    std::ostringstream ss;

    // RLE owner encoding
    std::vector<std::pair<int, int>> rle; // count, owner
    int current_owner = -1;
    int current_count = 0;

    for (int r = 0; r < map.height; ++r) {
        for (int c = 0; c < map.width; ++c) {
            int owner = map.contents[r][c].owner;
            if (owner == current_owner) {
                current_count++;
            } else {
                if (current_count > 0) {
                    rle.push_back({current_count, current_owner});
                }
                current_owner = owner;
                current_count = 1;
            }
        }
    }
    if (current_count > 0) {
        rle.push_back({current_count, current_owner});
    }

    for (size_t i = 0; i < rle.size(); ++i) {
        if (i > 0) ss << " ";
        ss << rle[i].first << " " << rle[i].second;
